22	#[RequiresPermission('*', servingNode: ServingNode::Gateway)]
23	final readonly class OperationStreamControlPlaneController
24	{
25	    public function __construct(
26	        private OperationStreamSubscriberLeases $leases,
27	        private OperationStreamTokens $tokens,
28	        private OperationEventRecorder $events,
29	        private OperationStreamFrameBroadcaster $broadcaster,
30	    ) {}
