32	    public function show(OperationRun $operationRun): JsonResponse
33	    {
34	        $channel = $this->channel($operationRun);
35	        $auth = $this->tokens->authToken($operationRun, $channel);
36	
37	        return response()->json(JsonEnvelope::success([
38	            'operation' => [
39	                'uuid' => $operationRun->id,
40	                'operation_id' => $operationRun->operation_id,
41	            ],
42	            'channel' => [
43	                'name' => $channel,
44	                'private' => true,
45	            ],
46	            'reverb' => [
47	                'app_key' => Config::string('broadcasting.connections.reverb.key'),
48	                'host' => Config::string('reverb.servers.reverb.hostname', 'localhost'),
49	                'port' => Config::integer('reverb.servers.reverb.port', 8080),
50	                'scheme' => Config::string('reverb.servers.reverb.scheme', 'http'),
51	            ],
52	            'auth' => [
53	                'endpoint' => "/api/operations/{$operationRun->id}/stream/auth",
54	                'method' => 'POST',
55	                'token' => $auth['token'],
56	                'expires_at' => $auth['expires_at']->toIso8601String(),
57	            ],
58	            'backfill' => $this->backfill($operationRun),
59	        ]));
60	    }
