62	    public function publisherCredentials(Request $request, OperationRun $operationRun): JsonResponse
63	    {
64	        $caller = $request->user();
65	
66	        if (! $caller instanceof Node || $operationRun->target_node_id !== $caller->id) {
67	            return $this->error(
68	                'authorization_failed',
69	                'Only the trusted target agent may mint publisher credentials.',
70	                [],
71	                403,
72	            );
73	        }
74	
75	        $channel = $this->channel($operationRun);
76	        $publisher = $this->tokens->publisherToken($operationRun, $channel);
77	
78	        return response()->json(JsonEnvelope::success([
79	            'operation' => [
80	                'uuid' => $operationRun->id,
81	                'operation_id' => $operationRun->operation_id,
82	            ],
83	            'channel' => [
84	                'name' => $channel,
85	                'private' => true,
86	            ],
87	            'publisher' => [
88	                'token' => $publisher['token'],
89	                'expires_at' => $publisher['expires_at']->toIso8601String(),
90	                'scope' => [
91	                    'operation_uuid' => $operationRun->id,
92	                    'channel' => $channel,
93	                    'target_node_id' => $operationRun->target_node_id,
94	                ],
95	            ],
96	        ]));
97	    }
