99	    public function publish(Request $request, OperationRun $operationRun): JsonResponse
100	    {
101	        $caller = $request->user();
102	
103	        if (! $caller instanceof Node || $operationRun->target_node_id !== $caller->id) {
104	            return $this->error(
105	                'authorization_failed',
106	                'Only the trusted target agent may publish operation stream frames.',
107	                [],
108	                403,
109	            );
110	        }
111	
112	        $data = $request->validate([
113	            'publisher_token' => ['required', 'string'],
114	            'frame' => ['required', 'array'],
115	            'frame.operation_uuid' => ['required', 'string'],
116	            'frame.channel' => ['required', 'string'],
117	            'frame.sequence' => ['required', 'integer', 'min:1'],
118	            'frame.emitted_at' => ['required', 'date'],
119	            'frame.type' => ['required', 'string', 'in:stdout,stderr,status,control,error,terminal'],
120	            'frame.payload' => ['required', 'array'],
121	        ]);
122	
123	        $channel = $this->channel($operationRun);
124	        $token = $this->tokens->verify($data['publisher_token'], $operationRun, $channel, 'publisher');
125	
126	        if ($token['expired']) {
127	            return $this->error(
128	                'operation_stream.publisher_expired',
129	                'The operation stream publisher token has expired.',
130	                [],
131	                403,
132	            );
133	        }
134	
135	        if (! $token['valid']) {
136	            return $this->error(
137	                'operation_stream.publisher_invalid',
138	                'The operation stream publisher token is invalid.',
139	                [],
140	                403,
141	            );
142	        }
143	
144	        if ($data['frame']['operation_uuid'] !== $operationRun->id) {
145	            return $this->error(
146	                'operation_stream.operation_denied',
147	                'The operation stream frame operation does not match the publish target.',
148	                [],
149	                403,
150	            );
151	        }
152	
153	        if ($data['frame']['channel'] !== $channel) {
154	            return $this->error(
155	                'operation_stream.channel_denied',
156	                'The operation stream frame channel does not match the publish target.',
157	                [],
158	                403,
159	            );
160	        }
161	
162	        $frame = [
163	            'operation_uuid' => $operationRun->id,
164	            'channel' => $channel,
165	            'sequence' => $data['frame']['sequence'],
166	            'emitted_at' => $data['frame']['emitted_at'],
167	            'source_node' => [
168	                'id' => $caller->id,
169	                'name' => $caller->name,
170	            ],
171	            'type' => $data['frame']['type'],
172	            'payload' => $data['frame']['payload'],
173	            'durable_replay_cursor' => [
174	                'operation_uuid' => $operationRun->id,
175	                'event_sequence' => null,
176	                'event_id' => null,
177	            ],
178	        ];
179	
180	        $event = $this->events->append($operationRun, 'operation_stream.frame', [
181	            'frame' => $frame,
182	        ]);
183	
184	        $frame['durable_replay_cursor'] = [
185	            'operation_uuid' => $operationRun->id,
186	            'event_sequence' => $event->sequence,
187	            'event_id' => $event->id,
188	        ];
189	
190	        $event->forceFill([
191	            'payload' => [
192	                'frame' => $frame,
193	            ],
194	        ])->save();
195	
196	        $broadcast = [
197	            'delivered' => true,
198	            'error' => null,
199	        ];
200	
201	        try {
202	            $this->broadcaster->broadcast($channel, $frame);
203	        } catch (Throwable $exception) {
204	            $broadcast = [
205	                'delivered' => false,
206	                'error' => [
207	                    'code' => 'operation_stream.broadcast_failed',
208	                    'message' => $exception->getMessage(),
209	                ],
210	            ];
211	        }
212	
213	        return response()->json(JsonEnvelope::success([
214	            'operation' => [
215	                'uuid' => $operationRun->id,
216	                'operation_id' => $operationRun->operation_id,
217	            ],
218	            'frame' => $frame,
219	            'broadcast' => $broadcast,
220	        ]));
221	    }
