223	    public function auth(Request $request, OperationRun $operationRun): JsonResponse
224	    {
225	        $data = $request->validate([
226	            'socket_id' => ['required', 'string'],
227	            'channel_name' => ['required', 'string'],
228	            'auth_token' => ['required', 'string'],
229	        ]);
230	
231	        $channel = $this->channel($operationRun);
232	
233	        if ($data['channel_name'] !== $channel) {
234	            return $this->error(
235	                'operation_stream.channel_denied',
236	                'The requested operation channel is not allowed.',
237	                [],
238	                403,
239	            );
240	        }
241	
242	        $token = $this->tokens->verify($data['auth_token'], $operationRun, $channel, 'subscriber');
243	
244	        if ($token['expired']) {
245	            return $this->error(
246	                'operation_stream.auth_expired',
247	                'The operation stream authorization token has expired.',
248	                [],
249	                403,
250	            );
251	        }
252	
253	        if (! $token['valid']) {
254	            return $this->error(
255	                'operation_stream.auth_invalid',
256	                'The operation stream authorization token is invalid.',
257	                [],
258	                403,
259	            );
260	        }
261	
262	        $lease = $this->leases->join($operationRun, $channel, $data['socket_id']);
263	
264	        return response()->json(JsonEnvelope::success([
265	            'channel' => $channel,
266	            'lease' => [
267	                'subscriber' => $lease['subscriber'],
268	                'active_subscribers' => $lease['active_subscribers'],
269	                'expires_at' => $lease['expires_at']->toIso8601String(),
270	            ],
271	        ]));
272	    }
273	
274	    public function leave(Request $request, OperationRun $operationRun): JsonResponse
275	    {
276	        $data = $request->validate([
277	            'socket_id' => ['required', 'string'],
278	        ]);
279	
280	        $channel = $this->channel($operationRun);
281	        $lease = $this->leases->leave($operationRun, $channel, $data['socket_id']);
282	
283	        return response()->json(JsonEnvelope::success([
284	            'channel' => $channel,
285	            'lease' => [
286	                'subscriber' => $lease['subscriber'],
287	                'active_subscribers' => $lease['active_subscribers'],
288	            ],
289	        ]));
290	    }
291	
292	    public function stopDecision(OperationRun $operationRun): JsonResponse
293	    {
294	        $channel = $this->channel($operationRun);
295	        $activeSubscribers = $this->leases->activeCount($operationRun, $channel);
296	
297	        return response()->json(JsonEnvelope::success([
298	            'operation' => [
299	                'uuid' => $operationRun->id,
300	            ],
301	            'channel' => [
302	                'name' => $channel,
303	            ],
304	            'active_subscribers' => $activeSubscribers,
305	            'should_stop_tail' => $activeSubscribers === 0,
306	        ]));
307	    }
308	
309	    private function channel(OperationRun $operationRun): string
310	    {
311	        return "private-operations.{$operationRun->id}";
312	    }
313	
314	    /**
315	     * @return array{cursor: int|null, from_sequence: int|null, available: int}
316	     */
317	    private function backfill(OperationRun $operationRun): array
318	    {
319	        $query = OperationEvent::query()->where('operation_run_id', $operationRun->id);
320	
321	        return [
322	            'cursor' => (clone $query)->max('sequence'),
323	            'from_sequence' => (clone $query)->min('sequence'),
324	            'available' => (clone $query)->count(),
325	        ];
326	    }
327	
328	    /**
329	     * @param  array<string, mixed>  $meta
330	     */
331	    private function error(string $code, string $message, array $meta, int $status): JsonResponse
332	    {
333	        return response()->json(JsonEnvelope::failure($code, $message, $meta), $status);
334	    }
335	}
