1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace App\Services\Operations;
6	
7	use App\Models\OperationRun;
8	use Illuminate\Support\Carbon;
9	use Illuminate\Support\Facades\Config;
10	use Illuminate\Support\Str;
11	use RuntimeException;
12	
13	final readonly class OperationStreamTokens
14	{
15	    /**
16	     * @return array{token: string, expires_at: Carbon}
17	     */
18	    public function authToken(OperationRun $operationRun, string $channel): array
19	    {
20	        return $this->token('subscriber', $operationRun, $channel, $this->authTtlSeconds());
21	    }
22	
23	    /**
24	     * @return array{token: string, expires_at: Carbon}
25	     */
26	    public function publisherToken(OperationRun $operationRun, string $channel): array
27	    {
28	        return $this->token('publisher', $operationRun, $channel, $this->publisherTtlSeconds());
29	    }
30	
31	    /**
32	     * @return array{valid: bool, expired: bool}
33	     */
34	    public function verify(string $token, OperationRun $operationRun, string $channel, string $purpose): array
35	    {
36	        $parts = explode('.', $token, 2);
37	
38	        if (count($parts) !== 2) {
39	            return ['valid' => false, 'expired' => false];
40	        }
41	
42	        [$payload, $signature] = $parts;
43	
44	        if (! hash_equals($this->sign($payload), $signature)) {
45	            return ['valid' => false, 'expired' => false];
46	        }
47	
48	        $decoded = json_decode((string) base64_decode($payload, true), true);
49	
50	        if (! is_array($decoded)) {
51	            return ['valid' => false, 'expired' => false];
52	        }
53	
54	        if (($decoded['purpose'] ?? null) !== $purpose) {
55	            return ['valid' => false, 'expired' => false];
56	        }
57	
58	        if (($decoded['operation_uuid'] ?? null) !== $operationRun->id) {
59	            return ['valid' => false, 'expired' => false];
60	        }
61	
62	        if (($decoded['channel'] ?? null) !== $channel) {
63	            return ['valid' => false, 'expired' => false];
64	        }
65	
66	        if ($purpose === 'publisher' && ($decoded['target_node_id'] ?? null) !== $operationRun->target_node_id) {
67	            return ['valid' => false, 'expired' => false];
68	        }
69	
70	        $expiresAt = $decoded['expires_at'] ?? null;
71	
72	        if (! is_int($expiresAt)) {
73	            return ['valid' => false, 'expired' => false];
74	        }
75	
76	        if (Carbon::createFromTimestamp($expiresAt)->lessThanOrEqualTo(Carbon::now())) {
77	            return ['valid' => false, 'expired' => true];
78	        }
79	
80	        return ['valid' => true, 'expired' => false];
81	    }
82	
83	    /**
84	     * @return array{token: string, expires_at: Carbon}
85	     */
86	    private function token(string $purpose, OperationRun $operationRun, string $channel, int $ttlSeconds): array
87	    {
88	        $expiresAt = Carbon::now()->addSeconds($ttlSeconds);
89	        $payload = base64_encode(json_encode([
90	            'id' => (string) Str::uuid(),
91	            'purpose' => $purpose,
92	            'operation_uuid' => $operationRun->id,
93	            'channel' => $channel,
94	            'target_node_id' => $operationRun->target_node_id,
95	            'expires_at' => $expiresAt->timestamp,
96	        ], JSON_THROW_ON_ERROR));
97	
98	        return [
99	            'token' => "{$payload}.{$this->sign($payload)}",
100	            'expires_at' => $expiresAt,
101	        ];
102	    }
103	
104	    private function sign(string $payload): string
105	    {
106	        return hash_hmac('sha256', $payload, $this->secret());
107	    }
108	
109	    private function secret(): string
110	    {
111	        $secret = Config::get('orbit.operation_token_secret');
112	
113	        if (is_string($secret) && $secret !== '') {
114	            return $secret;
115	        }
116	
117	        $appKey = Config::get('app.key');
118	
119	        if (is_string($appKey) && $appKey !== '') {
120	            return $appKey;
121	        }
122	
123	        throw new RuntimeException('Operation stream token signing requires orbit.operation_token_secret or app.key.');
124	    }
125	
126	    private function authTtlSeconds(): int
127	    {
128	        return max(1, Config::integer('orbit.operations.stream_auth_ttl_seconds', 300));
129	    }
130	
131	    private function publisherTtlSeconds(): int
132	    {
133	        return max(1, Config::integer('orbit.operations.publisher_token_ttl_seconds', 120));
134	    }
135	}
